// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Lottery {
    uint256 public constant CONFIRMATIONS = 12;
    uint256 public lastDrawBlock;
    bytes32 public committedEntropy;
    address public winner;

    function requestDraw() external {
        // Commit to future blockhash after CONFIRMATIONS blocks
        committedEntropy = blockhash(block.number + CONFIRMATIONS);
        lastDrawBlock = block.number + CONFIRMATIONS;
    }

    function revealDraw() external {
        require(block.number >= lastDrawBlock, "wait for finality");
        // Use the blockhash of the finalized block
        uint256 entropy = uint256(blockhash(lastDrawBlock));
        winner = payable(msg.sender); // simplified
    }

    function claimPrize() external {
        require(msg.sender == winner, "not winner");
        require(block.number > lastDrawBlock, "already claimed");
        payable(msg.sender).transfer(address(this).balance);
    }
}
